import java.io.*;

public class Main {
    static final int INF = 1000000001;

    static class Pair {
        int first, second;
        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    static int[] sort(int[] arr) {
        if (arr.length < 2) {
            return arr;
        }
        sort(arr, 0, arr.length - 1);
        return arr;
    }

    static void sort(int[] arr, int low, int high) {
        if (low >= high) return;
        int left = low;
        int right = high;
        int pivot = (low + high) / 2;

        int temp = arr[pivot];
        arr[pivot] = arr[right];
        arr[right] = temp;

        for (int i = low; i <= high; i++) {
            if (arr[i] < arr[right]) {
                temp = arr[i];
                arr[i] = arr[left];
                arr[left] = temp;
                left++;
            }
        }

        temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        sort(arr, low, left - 1);
        sort(arr, left + 1, high);
    }

    static boolean check(int n) {
        int s = 0;
        while (n > 0) {
            s += n % 10;
            n /= 10;
        }
        return s == 10;
    }

    static void solution(BufferedReader reader, PrintWriter writer) throws IOException {
        String line = reader.readLine();
        if (line == null) return;
        int k = Integer.parseInt(line.trim());
        for (int i = 19; k > 0; i++) {
            if (check(i)) {
                k--;
            }
            if (k == 0) {
                writer.println(i);
                return;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 1024 * 1024);
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1024 * 1024));
        try {
            solution(reader, writer);
        } finally {
            writer.flush();
        }
    }
}

